Method.Source:
/// <summary>
/// PaffH 10.12.21
/// </summary>
protected void new()
{
    userConnection = new UserConnection();
}

/// <summary>
/// PaffH 10.12.21
/// </summary>
/// <param name = "argsLogger">NDXIArgsLogger</param>
/// <returns>Common</returns>
abstract Common Start(NDXIArgsLogger argsLogger)
{
}

/// <summary>
/// PaffH 10.12.21
/// </summary>
/// <param name = "argsLogger">NDXIArgsLogger</param>
abstract void End(NDXIArgsLogger argsLogger)
{
}

/// <summary>
/// PaffH 10.12.21
/// </summary>
/// <param name = "argsLogger">NDXIArgsLogger</param>
abstract void LogLineCreate(NDXIArgsLogger argsLogger)
{
}

/// <summary>
/// PaffH 10.12.21
/// </summary>
/// <param name = "argsLogger">NDXIArgsLogger</param>
abstract void LogLineChange(NDXIArgsLogger argsLogger)
{
}

/// <summary>
/// PaffH 10.12.21
/// </summary>
/// <param name = "logTableRecord">LogTable record to delete</param>
/// <returns>deleted ?</returns>
public boolean DeleteLogTableRecord(Common logTableRecord)
{
    try
    {
        userConnection.ttsbegin();

        logTableRecord.setConnection(userConnection);
        logTableRecord.selectForUpdate(true);
        logTableRecord.delete();

        userConnection.ttscommit();
        return true;
    }
    catch
    {
        return false;
    }
}
